def letterCombinations(digits):
    """Generate all letter combinations for phone number digits."""
    if not digits:
        return []

    phone = {
        "2": "abc", "3": "def", "4": "ghi", "5": "jkl",
        "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"
    }
    result = []

    def backtrack(path, idx):
        # Base case: reached leaf (processed all digits)
        if idx == len(digits):
            result.append(path)
            return
        # Explore all letters for current digit
        for letter in phone[digits[idx]]:
            backtrack(path + letter, idx + 1)

    backtrack("", 0)
    return result
